def ref(line):
    ep=next(e for e in EPISODES if e['global_line_start']<=line<=e['global_line_end'])
    return dict(episode_id=ep['episode_id'],global_line=line,episode_line=line-ep['global_line_start']+1,text=LINES[line-1])

def build():
    result=[]; source_mentions=set(); assigned=set()
